final class Cache {
    private State state;                       // the representation: one reference

    void swapState(Cache other) {              // plain field exchange: cannot fail
        State t = state; state = other.state; other.state = t;
    }

    void commit(State fresh) { state = fresh; }        // publication
    // shared: AtomicReference<State> ref; ref.getAndSet(fresh);
    // lists:  Collections.swap(list, i, j);
}
